const a="/plugin.php?id=pokemon:api";async function c(r,e={}){const t=`${a}&endpoint=${r}&${new URLSearchParams(e)}`,n=await fetch(t,{credentials:"include"});if(!n.ok)throw new Error(`HTTP ${n.status}`);const o=await n.json();if(!o.success)throw new Error(o.error||o.reason||"Unknown error");return o}async function d(r,e){const t=new FormData;for(const[s,i]of Object.entries(e))t.append(s,typeof i=="object"?JSON.stringify(i):String(i));const n=await fetch(`${a}&endpoint=${r}`,{method:"POST",credentials:"include",body:t});if(!n.ok)throw new Error(`HTTP ${n.status}`);const o=await n.json();if(!o.success)throw new Error(o.error||o.reason||"Unknown error");return o}async function p(r,e={}){const t=new URLSearchParams;t.append("action",r);for(const[o,s]of Object.entries(e))t.append(o,typeof s=="object"?JSON.stringify(s):String(s));const n=await fetch(`${a}&endpoint=admin`,{method:"POST",credentials:"include",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:t.toString()});if(!n.ok)throw new Error(`HTTP ${n.status}`);return n.json()}const w={get:c,post:d,admin:p};export{w as api};
